.separator { flex: none; background: var(--rule); border: 0; }
.separator[data-orientation="horizontal"] { height: 1px; width: 100%; margin: var(--s4) 0; }
.separator[data-orientation="vertical"] { width: 1px; align-self: stretch; margin: 0 var(--s3); }

